package com.marketplace.adapters.in.web.party;
import com.marketplace.application.party.PartyUseCase; import com.marketplace.domain.party.PartyType; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.List;
@RestController @RequestMapping("/api/customers") public class CustomerController { private final PartyUseCase u; public CustomerController(PartyUseCase u){this.u=u;} @GetMapping public List<PartyUseCase.View> list(){return u.list(PartyType.CUSTOMER);}@GetMapping("/{id}") public PartyUseCase.View get(@PathVariable Long id){return u.get(id,PartyType.CUSTOMER);}@PostMapping public ResponseEntity<PartyUseCase.View> create(@Valid @RequestBody PartyRequest r){var x=u.create(PartyType.CUSTOMER,cmd(r));return ResponseEntity.created(URI.create("/api/customers/"+x.id())).body(x);}@PutMapping("/{id}") public PartyUseCase.View update(@PathVariable Long id,@Valid @RequestBody PartyRequest r){return u.update(id,PartyType.CUSTOMER,cmd(r));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){u.deactivate(id,PartyType.CUSTOMER);} private static PartyUseCase.Command cmd(PartyRequest r){return new PartyUseCase.Command(r.name(),r.email(),r.document(),r.active()==null||r.active());} }
